import re
def tr(s, li):
    keys = sorted(G, key=len, reverse=True)
    rx = re.compile(r'(?<![\w])(' + '|'.join(re.escape(k) for k in keys) + r')(?![\w])')
    return rx.sub(lambda m: G[m.group(1)][li], s)
